/**
 * Test direct sending of locally generated PDF
 */

require('dotenv').config();
const fs = require('fs');

async function testDirectSend() {
  console.log('🧪 Testing direct send of working PDF...\n');

  try {
    // Use the PDF that was generated by the working test at 10:19
    const workingPdf = fs.readFileSync('./test-output.pdf');
    console.log(`📄 Working PDF: ${(workingPdf.length / 1024).toFixed(1)}KB`);

    const { Resend } = require('resend');
    const resend = new Resend(process.env.RESEND_API_KEY);

    const result = await resend.emails.send({
      from: 'onboarding@resend.dev',
      to: 'eros@rb2.nl',
      subject: 'DIRECT SEND: Working PDF from 10:19 Test',
      html: `
        <div style="font-family: Inter, sans-serif; max-width: 500px; margin: 0 auto; padding: 20px;">
          <h2 style="color: #10B981;">📎 Direct Send Test</h2>
          <p>This email contains the EXACT PDF that was generated by the working 10:19 test.</p>
          <p><strong>This PDF worked when generated by test-lead-flow.cjs at 10:19</strong></p>
          <p>If this fails too, the problem is in email encoding, not PDF generation.</p>
        </div>
      `,
      attachments: [{
        filename: 'Working-10-19-Test.pdf',
        content: workingPdf.toString('base64'),
        contentType: 'application/pdf',
      }],
    });

    console.log('✅ Direct send email sent:', result.data?.id || result.id);
    console.log('📬 This uses the EXACT working PDF from 10:19');

  } catch (error) {
    console.error('❌ Error:', error);
  }
}

testDirectSend();